#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"


/* Array initialization. */
static
void init_array(int n,
                DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
                DATA_TYPE POLYBENCH_1D(x,N,n),
                DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Create restrict-qualified local aliases to help the optimizer.
     This is safe in the PolyBench setting where arrays do not alias. */
  DATA_TYPE (*restrict L_)[n] = L;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict b_ = b;

  for (i = 0; i < n; i++)
    {
      x_[i] = (DATA_TYPE)-999;
      b_[i] = (DATA_TYPE)i;

      /* Cache the current row pointer to improve locality and
         reduce address computation in the inner loop. */
      DATA_TYPE *restrict Lrow = L_[i];

      for (j = 0; j <= i; j++)
        Lrow[j] = (DATA_TYPE) (i + n - j + 1) * 2 / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */

static
void kernel_trisolv [[gnu::flatten, gnu::noinline]] (int n,
                    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
                    DATA_TYPE POLYBENCH_1D(x,N,n),
                    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases to give the compiler stronger
     guarantees about aliasing and enable better vectorization. */
  DATA_TYPE (*restrict L_)[n] = L;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict b_ = b;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Cache the current row to improve spatial locality and avoid
         repeated 2D indexing computations. */
      DATA_TYPE *restrict Lrow = L_[i];

      /* Start from b[i] and subtract the dot product L[i][0..i-1]·x[0..i-1]. */
      DATA_TYPE xi = b_[i];

      /* Manually unrolled inner loop for better ILP and to aid the
         compiler's vectorizer. The arithmetic order is preserved:
         we still perform the subtractions in increasing j order. */
      int limit = (i / 4) * 4;

      for (j = 0; j < limit; j += 4)
        {
          xi -= Lrow[j]   * x_[j];
          xi -= Lrow[j+1] * x_[j+1];
          xi -= Lrow[j+2] * x_[j+2];
          xi -= Lrow[j+3] * x_[j+3];
        }

      /* Remainder loop for the last 0–3 elements. */
      for (; j < i; j++)
        {
          xi -= Lrow[j] * x_[j];
        }

      /* Divide once at the end; equivalent to the original
         x[i] = x[i] / L[i][i] in terms of evaluation order. */
      xi /= Lrow[i];
      x_[i] = xi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
