		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Use restrict-qualified local pointers to help the compiler
   * optimize assuming no aliasing between L, x and b.
   */
  DATA_TYPE (*restrict Lr)[n] = L;
  DATA_TYPE *restrict xr = x;
  DATA_TYPE *restrict br = b;

  for (i = 0; i < n; i++)
    {
      xr[i] = (DATA_TYPE)-999;
      br[i] = (DATA_TYPE)i;

      /* Access the current row once, through a row pointer. */
      DATA_TYPE *restrict Li = Lr[i];

      /* Original formula:
       *   L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n;
       *
       * This is pure integer arithmetic followed by a cast.
       * We algebraically factor the numerator to reduce work
       * in the inner loop, but keep it mathematically identical:
       *
       *   (i + n - j + 1) * 2
       *   = ( (i + n + 1) - j ) * 2
       *   = (i + n + 1) * 2 - 2*j
       *
       * So for a fixed i we can maintain a decrementing numerator:
       *   base = (i + n + 1) * 2;
       *   num  = base - 2*j;
       *   value = (DATA_TYPE)(num / n);
       *
       * All operations are in int, so this preserves bit-exact
       * results compared to the original expression.
       */
      int base = (i + n + 1) * 2;
      int num  = base;

      for (j = 0; j <= i; j++)
      {
        Li[j] = (DATA_TYPE)(num / n);
        num -= 2;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


