   including the call and return. */
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Use restrict-qualified local pointers to tell the compiler that
   * the three arrays do not alias. This enables better vectorization
   * and register promotion.
   */
  DATA_TYPE (*restrict Lr)[n] = L;
  DATA_TYPE *restrict xr = x;
  DATA_TYPE *restrict br = b;

#pragma scop
  /* Forward substitution for a lower-triangular system:
   *
   * Original code (conceptually):
   *   for i = 0.._PB_N-1:
   *     x[i] = b[i];
   *     for j = 0..i-1:
   *       x[i] -= L[i][j] * x[j];
   *     x[i] = x[i] / L[i][i];
   *
   * Optimizations applied:
   *   - Keep the running value for x[i] in a local variable 'xi'
   *     to avoid repeated loads/stores of x[i].
   *   - Use a row pointer Li for L[i][*] to improve cache locality
   *     and simplify index expressions.
   *   - Manually unroll the inner loop by a factor of 4 while
   *     preserving the exact order of floating-point operations.
   *     This improves ILP without changing the arithmetic sequence.
   */
  for (i = 0; i < _PB_N; i++)
    {
      DATA_TYPE *restrict Li = Lr[i];
      DATA_TYPE xi = br[i];

      j = 0;

      /* Manually unrolled loop: the four subtractions are executed
       * in the same j order as in the original scalar loop, so
       * floating‑point semantics (operation order) are preserved.
       */
      for (; j + 3 < i; j += 4)
      {
        xi -= Li[j    ] * xr[j    ];
        xi -= Li[j + 1] * xr[j + 1];
        xi -= Li[j + 2] * xr[j + 2];
        xi -= Li[j + 3] * xr[j + 3];
      }

      /* Cleanup loop for any remaining iterations. */
      for (; j < i; j++)
      {
        xi -= Li[j] * xr[j];
      }

      /* Final division, as in the original code. */
      xi = xi / Li[i];

      xr[i] = xi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

