         */
        int tmp = (i + n - j + 1) * 2 / n;
        Li[j] = (DATA_TYPE)tmp;
      }
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Use restrict-qualified local aliases for L, x, and b to remove
 *    potential aliasing and enable more aggressive optimizations.
 *  - Keep a per-row pointer (Li) so inner loop accesses are simple
 *    pointer arithmetic instead of 2D indexing.
 *  - Use a scalar accumulator (xi) that mirrors the original recurrence
 *    x[i] -= L[i][j] * x[j]; this preserves the left-to-right order of
 *    floating-point operations while avoiding repeated memory stores.
 *  - Manually unroll the inner loop by a factor of 4 to reduce loop
 *    overhead and improve autovectorization opportunities. Edge cases
 *    (i not divisible by 4) are handled by a cleanup loop.
 */
static
void __attribute__((noinline, hot))
kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Local restrict aliases for better optimization.  PolyBench guarantees
   * these arrays are allocated disjointly, so the restrict assumptions hold.
   */
  DATA_TYPE (*restrict L_)[n]      = L;
  DATA_TYPE *restrict x_           = x;
  const DATA_TYPE *restrict b_     = b;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      const DATA_TYPE *restrict Li = L_[i];
      DATA_TYPE xi = b_[i];

      /* Manually unrolled inner loop (factor 4).
       * limit = largest multiple of 4 less than or equal to i.
       */
      j = 0;
      int limit = i & ~3; /* bitwise clear last two bits -> multiple of 4 */

      for (; j < limit; j += 4)
      {
        xi -= Li[j]     * x_[j];
        xi -= Li[j + 1] * x_[j + 1];
        xi -= Li[j + 2] * x_[j + 2];
        xi -= Li[j + 3] * x_[j + 3];
      }

      /* Remainder iterations (0–3 elements). */
      for (; j < i; j++)
      {
        xi -= Li[j] * x_[j];
      }

      /* Final division as in the original code. */
      xi /= Li[i];
      x_[i] = xi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
